.text-btn:disabled {
  color: var(--muted-dim);
  border-color: rgba(255, 255, 255, 0.07);
  background: transparent;
  cursor: not-allowed;
}

.achievements-link {
  display: flex;
  flex: 0 0 auto;
  min-height: 38px;
  align-items: center;
  gap: 8px;
  margin-top: auto;
  padding: 0 10px;
  color: var(--muted);
  border: 1px solid rgba(255, 255, 255, 0.06);
  background: rgba(255, 255, 255, 0.018);
  font-family: var(--font-mono);
  font-size: 8px;
  font-weight: 700;
  letter-spacing: 0.12em;
  cursor: pointer;
}

.system-panel .achievements-link {
  margin-top: 10px;
}

.achievements-link b {
  margin-left: auto;
  color: var(--amber);
}

.achievements-link .arrow {
  color: var(--red);
  font-size: 13px;
}

.achievements-link:hover {
  color: var(--text);
  border-color: var(--line);
}

/* ─────────────────────── CORE STAGE ─────────────────────── */

.core-stage {
  position: relative;
  display: flex;
  min-width: 0;
  min-height: 0;
  flex-direction: column;
  align-items: center;
  justify-content: space-between;
  padding: 2px 4px 0;
  overflow: hidden;
}

.core-stage::before {
  content: "";
  position: absolute;
  top: 8%;
  left: 50%;
  width: min(80%, 620px);
  height: 75%;
  transform: translateX(-50%);
  background: radial-gradient(circle, rgba(255, 53, 87, 0.09), transparent 63%);
  pointer-events: none;
}

.stage-topline {
  z-index: 4;
  display: flex;
  width: 100%;
  align-items: center;
  justify-content: space-between;
  gap: 10px;
  padding: 0 6px;
  color: var(--muted);
  font-family: var(--font-mono);
  font-size: 8px;
  font-weight: 600;
  letter-spacing: 0.1em;
}

.stage-status {
  display: inline-flex;
  align-items: center;
  gap: 6px;
}

.stage-status i {
  width: 5px;
  height: 5px;
  background: var(--red);
  box-shadow: 0 0 8px var(--red);
  animation: status-blink 1.3s infinite;
}

.combo-readout {
  padding: 4px 7px;
  color: var(--muted-dim);
  border: 1px solid rgba(255, 255, 255, 0.06);
  background: rgba(0, 0, 0, 0.16);
  transition: color 160ms ease, border-color 160ms ease;
}

.combo-readout b {
  color: var(--amber);
  font-size: 9px;
}

.core-stage.hot .combo-readout {
  color: var(--amber);
  border-color: rgba(255, 209, 102, 0.3);
  box-shadow: 0 0 16px rgba(255, 209, 102, 0.08);
}

.reactor {
  position: relative;
  display: grid;
  width: min(56vh, 478px);
  max-width: 100%;
  aspect-ratio: 1;
  place-items: center;
  margin: -2px 0 -3px;
  isolation: isolate;
}

.reactor-halo {
  position: absolute;
  inset: 10%;
  z-index: -1;
  border-radius: 50%;
  background: radial-gradient(circle, rgba(255, 53, 87, 0.22) 0%, rgba(255, 53, 87, 0.045) 42%, transparent 68%);
  filter: blur(14px);
  animation: halo-breathe 4.8s ease-in-out infinite;
}

.orbit {
  position: absolute;
  border-radius: 50%;
  pointer-events: none;
}

.orbit-a {
  inset: 3.8%;
  border: 1px dashed rgba(255, 77, 105, 0.22);
  animation: orbit-spin 36s linear infinite;
}

.orbit-a::before,
.orbit-a::after {
  content: "";
  position: absolute;
  width: 5px;
  height: 5px;
  border-radius: 50%;
  background: var(--red);
  box-shadow: 0 0 10px var(--red);
}

.orbit-a::before {
  top: 8%;
  left: 21%;
}

.orbit-a::after {
  right: 12%;
  bottom: 21%;
  width: 3px;
  height: 3px;
  background: var(--amber);
  box-shadow: 0 0 8px var(--amber);
}

.orbit-a i {
  position: absolute;
  top: 50%;
  left: 50%;
  color: rgba(255, 209, 102, 0.42);
  font-family: var(--font-mono);
  font-size: 8px;
  font-style: normal;
}

.orbit-a i:first-child {
  transform: translate(-50%, -50%) translateY(-235px);
}

.orbit-a i:last-child {
  transform: translate(-50%, -50%) translateY(233px);
}

.orbit-b {
  inset: 14%;
  border: 1px solid rgba(255, 255, 255, 0.055);
  border-top-color: rgba(255, 209, 102, 0.27);
  border-right-color: rgba(255, 53, 87, 0.23);
  animation: orbit-spin-reverse 27s linear infinite;
}

.orbit-b::before {
  content: "";
  position: absolute;
  inset: 9px;
  border-radius: 50%;
  border: 1px dotted rgba(255, 255, 255, 0.09);
}

.orbit-b i {
  position: absolute;
  top: -4px;
  left: 50%;
  width: 7px;
  height: 7px;
  transform: translateX(-50%) rotate(45deg);
  border: 1px solid var(--amber);
  background: #1b130a;
  box-shadow: 0 0 12px rgba(255, 209, 102, 0.5);
}

.orbit-c {
  inset: 22.5%;
  border: 1px dashed rgba(255, 255, 255, 0.1);
  animation: orbit-spin 19s linear infinite;
}

.orbit-c::before,
.orbit-c::after {
  content: "✕";
  position: absolute;
  color: rgba(255, 77, 105, 0.42);
  font-family: var(--font-mono);
  font-size: 8px;
}

.orbit-c::before {
  top: 4%;
  right: 15%;
}

.orbit-c::after {
  bottom: 4%;
  left: 15%;
}

.runes {
  position: absolute;
  top: 50%;
  z-index: 1;
  color: rgba(255, 77, 105, 0.25);
  font-family: var(--font-mono);
  font-size: 7px;
  line-height: 2.4;
  letter-spacing: 0.08em;
  text-align: center;
  pointer-events: none;
}

.runes-left {
  left: 2.5%;
  transform: translateY(-50%);
}

.runes-right {
  right: 2.5%;
  transform: translateY(-50%);
}

.solver-core {
  position: relative;
  display: flex;
  width: 61%;
  aspect-ratio: 1;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  padding: 0;
  color: var(--text);
  border: 1px solid rgba(255, 77, 105, 0.5);
  border-radius: 50%;
  background:
    radial-gradient(circle at 50% 43%, rgba(80, 12, 23, 0.72), rgba(10, 6, 10, 0.98) 56%, #050407 72%),
    #080509;
  box-shadow:
    0 0 0 8px rgba(255, 53, 87, 0.025),
    0 0 0 9px rgba(255, 77, 105, 0.09),
    0 0 45px rgba(255, 53, 87, 0.25),
    inset 0 0 56px rgba(255, 53, 87, 0.11),
    inset 0 0 0 5px rgba(255, 255, 255, 0.018);
  cursor: pointer;
  touch-action: manipulation;
  user-select: none;
  -webkit-user-select: none;
  transition: filter 160ms ease, box-shadow 200ms ease;
}

.solver-core::before {
  content: "";
  position: absolute;
  inset: 6.5%;
  border: 1px dashed rgba(255, 209, 102, 0.16);
  border-radius: 50%;
  animation: orbit-spin 60s linear infinite;
}

.solver-core::after {
  content: "";
  position: absolute;
  inset: 13%;
  border: 1px solid rgba(255, 255, 255, 0.045);
  border-radius: 50%;
}

.solver-core:hover {
  filter: brightness(1.16);
  box-shadow:
    0 0 0 8px rgba(255, 53, 87, 0.04),
    0 0 0 9px rgba(255, 77, 105, 0.2),
    0 0 70px rgba(255, 53, 87, 0.4),
    inset 0 0 70px rgba(255, 53, 87, 0.16),
    inset 0 0 0 5px rgba(255, 255, 255, 0.03);
}

.solver-core:active {
  transform: scale(0.972);
}

.solver-core.is-hit {
  animation: core-hit 150ms ease-out;
}

.core-pulse {
  position: absolute;
  inset: -1px;
  z-index: -1;
  border: 1px solid rgba(255, 53, 87, 0.55);
  border-radius: 50%;
  opacity: 0;
  pointer-events: none;
}

.solver-core.is-hit .core-pulse {
  animation: core-pulse 620ms ease-out;
}

.core-grid {
  position: absolute;
  inset: 18%;
  border-radius: 50%;
  opacity: 0.22;
  background:
    repeating-linear-gradient(0deg, transparent 0 10px, rgba(255, 77, 105, 0.22) 10px 11px),
    repeating-linear-gradient(90deg, transparent 0 10px, rgba(255, 77, 105, 0.22) 10px 11px);
  mask-image: radial-gradient(circle, #000 20%, transparent 70%);
  -webkit-mask-image: radial-gradient(circle, #000 20%, transparent 70%);
  pointer-events: none;
}

.solver-sigil {
  position: relative;
  width: 55%;
  height: auto;
  overflow: visible;
  filter: drop-shadow(0 0 10px rgba(255, 53, 87, 0.4));
  pointer-events: none;
  animation: sigil-float 6s ease-in-out infinite;
}

.sigil-core-path {
  animation: sigil-dash 4s linear infinite;
}

.core-copy {
  position: absolute;
  bottom: 13%;
  left: 50%;
  display: flex;
  flex-direction: column;
  align-items: center;
  transform: translateX(-50%);
  pointer-events: none;
}

.solve-label {
  color: var(--text);
  font-size: clamp(17px, 1.55vw, 23px);
  font-weight: 900;
  letter-spacing: 0.2em;
  line-height: 1;
  text-shadow: 0 0 16px rgba(255, 53, 87, 0.6);
}

.solve-sub {
  margin-top: 4px;
  color: var(--muted);
  font-family: var(--font-mono);
  font-size: 7px;
  font-weight: 600;
  letter-spacing: 0.08em;
  white-space: nowrap;
}

.solve-sub b {
  color: var(--amber);
}

.corner-mark {
  position: absolute;
  width: 9px;
  height: 9px;
  border-color: rgba(255, 209, 102, 0.45);
  border-style: solid;
  pointer-events: none;
}

.corner-tl {
  top: 12%;
  left: 17%;
  border-width: 1px 0 0 1px;
}

.corner-tr {
  top: 12%;
  right: 17%;
  border-width: 1px 1px 0 0;
}

.corner-bl {
  bottom: 12%;
  left: 17%;
  border-width: 0 0 1px 1px;
}

.corner-br {
  right: 17%;
  bottom: 12%;
  border-width: 0 1px 1px 0;
}

.core-stage.hot .solver-core {
  box-shadow:
    0 0 0 8px rgba(255, 53, 87, 0.045),
    0 0 0 9px rgba(255, 77, 105, 0.16),
    0 0 80px rgba(255, 53, 87, 0.36),
    inset 0 0 70px rgba(255, 53, 87, 0.16);
}

.core-stage.absolute .solver-core {
  border-color: var(--amber);
  box-shadow:
    0 0 0 9px rgba(255, 209, 102, 0.06),
    0 0 0 10px rgba(255, 53, 87, 0.22),
    0 0 95px rgba(255, 53, 87, 0.55),
    inset 0 0 70px rgba(255, 209, 102, 0.11);
}

.core-stage.absolute .orbit-a {
  border-color: rgba(255, 209, 102, 0.34);
}

.core-stage.absolute .reactor-halo {
  background: radial-gradient(circle, rgba(255, 53, 87, 0.34), rgba(255, 209, 102, 0.06) 45%, transparent 68%);
}

.core-hint {
  z-index: 3;
  margin: 0;
  color: var(--muted-dim);
  font-family: var(--font-mono);
  font-size: 8px;
  letter-spacing: 0.06em;
  text-align: center;
}

.core-hint kbd {
  margin-right: 3px;
  color: var(--amber);
  border-color: rgba(255, 209, 102, 0.18);
}

.stage-bottom {
  display: flex;
  width: 100%;
  justify-content: center;
  gap: clamp(16px, 4vw, 44px);
  padding: 8px 6px 0;
  border-top: 1px solid rgba(255, 255, 255, 0.055);
}

.tick-stat {
  display: flex;
  min-width: 80px;
  flex-direction: column;
  gap: 3px;
  align-items: center;
}

.tick-stat span {
  color: var(--muted-dim);
  font-family: var(--font-mono);
  font-size: 7px;
  font-weight: 600;
  letter-spacing: 0.1em;
}

.tick-stat b {
  color: var(--text);
  font-family: var(--font-mono);
  font-size: 11px;
  letter-spacing: -0.02em;
  font-variant-numeric: tabular-nums;
}

/* ─────────────────────── FX / ANOMALY ─────────────────────── */

.floating-layer,
.anomaly-layer {
  position: absolute;
  inset: 0;
  pointer-events: none;
}

.anomaly-layer {
  z-index: 9;
}

.float-gain {
  position: fixed;
  z-index: 30;
  color: var(--amber);
  font-family: var(--font-mono);
  font-size: 13px;
  font-weight: 800;
  text-shadow: 0 0 9px rgba(255, 209, 102, 0.55);
  pointer-events: none;
  animation: float-up 900ms cubic-bezier(0.1, 0.7, 0.3, 1) forwards;
}

.float-gain.crit {
  color: var(--red-hot);
  font-size: 19px;
  text-shadow: 0 0 14px rgba(255, 53, 87, 0.8);
}

.click-spark {
  position: fixed;
  z-index: 29;
  width: 5px;
  height: 5px;
  border: 1px solid var(--amber);
  pointer-events: none;
  animation: spark-fly 520ms ease-out forwards;
}

.click-spark:nth-child(3n) {
  background: var(--red);
  border-color: var(--red);
}

.click-spark:nth-child(3n + 1) {
  transform: rotate(45deg);
}

.anomaly {
  position: absolute;
  z-index: 11;
  display: grid;
  width: 58px;
  height: 58px;
  padding: 0;
  place-items: center;
  border: 1px solid var(--red);
  border-radius: 50%;
  background: radial-gradient(circle, rgba(255, 53, 87, 0.3), rgba(10, 5, 9, 0.94) 63%);
  box-shadow: 0 0 28px rgba(255, 53, 87, 0.5), inset 0 0 12px rgba(255, 53, 87, 0.25);
  cursor: crosshair;
  pointer-events: auto;
  transform: translate(-50%, -50%);
  animation: anomaly-in 320ms cubic-bezier(0.16, 1, 0.3, 1), anomaly-pulse 1.3s ease-in-out 320ms infinite;
}

.anomaly::before {
  content: "";
  position: absolute;
  inset: -7px;
  border: 1px dashed rgba(255, 209, 102, 0.4);
  border-radius: 50%;
  animation: orbit-spin 7s linear infinite;
}

.anomaly svg {
  width: 34px;
  height: 34px;
  overflow: visible;
  fill: none;
  stroke: var(--red-hot);
  stroke-width: 1.5;
  filter: drop-shadow(0 0 6px var(--red));
}

.anomaly .anomaly-timer {
  position: absolute;
  bottom: -18px;
  left: 50%;
  color: var(--amber);
  font-family: var(--font-mono);
  font-size: 8px;
  transform: translateX(-50%);
  white-space: nowrap;
}

.anomaly::after {
  content: "АНОМАЛИЯ";
  position: absolute;
  top: -18px;
  left: 50%;
  color: var(--red-hot);
  font-family: var(--font-mono);
  font-size: 7px;
  letter-spacing: 0.12em;
  transform: translateX(-50%);
  white-space: nowrap;
}

/* ─────────────────────── SHOP ─────────────────────── */

.shop-panel {
  display: flex;
  flex-direction: column;
  padding-bottom: 11px;
  overflow: hidden;
}

.shop-heading {
  flex: 0 0 auto;
}

.owned-pill {
  color: var(--amber);
  border-color: rgba(255, 209, 102, 0.17);
  background: rgba(255, 209, 102, 0.035);
}

.owned-pill b {
  color: var(--amber);
}

.shop-tabs {
  display: grid;
  flex: 0 0 auto;
  grid-template-columns: 1fr 1fr;
  margin: 11px 13px 0;
  border: 1px solid rgba(255, 255, 255, 0.07);
}

.shop-tab {
  display: flex;
  min-height: 35px;
  align-items: center;
  justify-content: space-between;
  gap: 6px;
  padding: 0 9px;
  color: var(--muted-dim);
  border: 0;
  background: transparent;
  font-family: var(--font-mono);
  font-size: 7.5px;
  font-weight: 700;
  letter-spacing: 0.08em;
  cursor: pointer;
  transition: color 150ms ease, background 150ms ease;
}

.shop-tab + .shop-tab {
  border-left: 1px solid rgba(255, 255, 255, 0.07);
}

.shop-tab span {
  color: var(--muted);
  font-size: 7px;
  font-weight: 500;
}

.shop-tab:hover {
  color: var(--text);
}

.shop-tab.active {
  color: var(--text);
  background: linear-gradient(180deg, rgba(255, 53, 87, 0.1), rgba(255, 53, 87, 0.025));
  box-shadow: inset 0 -1px 0 var(--red);
}

.shop-tab.active span {
  color: var(--amber);
}

.buy-mode-row {
  display: flex;
  flex: 0 0 auto;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
  padding: 9px 13px 7px;
}

.segmented {
  display: flex;
  border: 1px solid rgba(255, 255, 255, 0.08);
}

.segmented button {
  min-width: 34px;
  height: 23px;
  padding: 0 5px;
  color: var(--muted-dim);
  border: 0;
  background: transparent;
  font-family: var(--font-mono);
  font-size: 7px;
  font-weight: 700;
  cursor: pointer;
}

.segmented button + button {
  border-left: 1px solid rgba(255, 255, 255, 0.08);
}

.segmented button.active {
  color: var(--amber);
  background: rgba(255, 209, 102, 0.08);
}

.shop-list {
  display: flex;
  min-height: 0;
  flex: 1;
  flex-direction: column;
  gap: 6px;
  padding: 2px 12px 4px;
  overflow-y: auto;
  scrollbar-width: thin;
  scrollbar-color: rgba(255, 53, 87, 0.25) transparent;
}

.shop-list::-webkit-scrollbar {
  width: 4px;
}

.shop-list::-webkit-scrollbar-thumb {
  background: rgba(255, 53, 87, 0.25);
}

.shop-item {
  position: relative;
  display: grid;
  flex: 0 0 auto;
  grid-template-columns: 38px minmax(0, 1fr) auto;
  gap: 8px;
  align-items: center;
  min-height: 57px;
  padding: 7px 8px;
  border: 1px solid rgba(255, 255, 255, 0.055);
  background: rgba(255, 255, 255, 0.016);
  transition: border-color 160ms ease, background 160ms ease;
}

.shop-item:hover {
  border-color: rgba(255, 77, 105, 0.2);
  background: rgba(255, 53, 87, 0.025);
}

.shop-item.affordable {
  border-color: rgba(255, 209, 102, 0.16);
}

.shop-item.locked {
  opacity: 0.58;
}

.shop-icon {
  display: grid;
  width: 38px;
  height: 38px;
  place-items: center;
  color: var(--red);
  border: 1px solid rgba(255, 77, 105, 0.17);
  background:
    radial-gradient(circle at 50% 30%, rgba(255, 53, 87, 0.12), transparent 70%),
    rgba(0, 0, 0, 0.18);
}

.shop-icon svg {
  width: 24px;
  height: 24px;
  overflow: visible;
  fill: none;
  stroke: currentColor;
  stroke-width: 1.4;
  stroke-linecap: round;
  stroke-linejoin: round;
}

.shop-item[data-tone="amber"] .shop-icon {
  color: var(--amber);
  border-color: rgba(255, 209, 102, 0.18);
}

.shop-item[data-tone="violet"] .shop-icon {
  color: var(--violet);
  border-color: rgba(185, 146, 255, 0.18);
}

.shop-info {
  display: flex;
  min-width: 0;
  flex-direction: column;
  gap: 3px;
}

.shop-name-row {
  display: flex;
  align-items: center;
  gap: 6px;
  min-width: 0;
}

.shop-name {
  overflow: hidden;
  color: var(--text);
  font-size: 12px;
  font-weight: 800;
  letter-spacing: 0.035em;
  line-height: 1.1;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.shop-level {
  flex: 0 0 auto;
  color: var(--muted-dim);
  font-family: var(--font-mono);
  font-size: 7px;
  letter-spacing: 0.05em;
}

.shop-desc {
  overflow: hidden;
  color: var(--muted);
  font-size: 8.5px;
  line-height: 1.2;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.shop-yield {
  color: var(--amber);
  font-family: var(--font-mono);
  font-size: 7px;
  letter-spacing: 0.02em;
  white-space: nowrap;
}

.shop-buy {
  display: flex;
  min-width: 67px;
  flex-direction: column;
  align-items: flex-end;
  justify-content: center;
  gap: 3px;
  padding: 5px 6px;
  color: var(--muted);
  border: 1px solid rgba(255, 255, 255, 0.09);
  background: rgba(255, 255, 255, 0.025);
  cursor: pointer;
  transition: all 150ms ease;
}

.shop-buy .cost {
  color: var(--text);
  font-family: var(--font-mono);
  font-size: 9px;
  font-weight: 700;
  letter-spacing: -0.02em;
  white-space: nowrap;
}

.shop-buy .cost::before {
  content: "⬡ ";
  color: var(--amber);
  font-size: 7px;
}

.shop-buy .buy-label {
  color: var(--muted-dim);
  font-family: var(--font-mono);
  font-size: 6px;
  font-weight: 700;
  letter-spacing: 0.09em;
}

.shop-buy:hover:not(:disabled) {
  color: var(--amber);
  border-color: rgba(255, 209, 102, 0.38);
  background: rgba(255, 209, 102, 0.07);
}

.shop-buy:disabled {
  cursor: not-allowed;
  opacity: 0.38;
}

.shop-item.affordable .shop-buy {
  border-color: rgba(255, 209, 102, 0.28);
  background: rgba(255, 209, 102, 0.055);
}

.shop-item.affordable .shop-buy .cost {
  color: var(--amber);
}

.shop-tip {
  display: flex;
  flex: 0 0 auto;
  gap: 8px;
  margin: 8px 12px 0;
  padding: 8px 9px;
  border-top: 1px solid rgba(255, 255, 255, 0.055);
}

.tip-mark {
  display: grid;
  flex: 0 0 auto;
  width: 15px;
  height: 15px;
  place-items: center;
  color: var(--amber);
  border: 1px solid rgba(255, 209, 102, 0.3);
  font-family: var(--font-mono);
  font-size: 8px;
  font-weight: 700;
}

.shop-tip p {
  margin: 0;
  color: var(--muted-dim);
  font-size: 8.5px;
  line-height: 1.3;
}

/* ─────────────────────── TERMINAL ─────────────────────── */

.terminal-bar {
  display: grid;
  grid-template-columns: auto minmax(0, 1fr) auto;
  align-items: center;
  gap: 14px;
  padding: 0 24px;
  color: var(--muted);
  border-top: 1px solid rgba(255, 77, 105, 0.14);
  background: rgba(5, 4, 7, 0.88);
  font-family: var(--font-mono);
  font-size: 8px;
  letter-spacing: 0.04em;
}

.terminal-label {
  display: flex;
  align-items: center;
  gap: 6px;
  color: var(--red);
  font-weight: 700;
  letter-spacing: 0.12em;
  white-space: nowrap;
}

.terminal-label i {
  width: 4px;
  height: 4px;
  border-radius: 50%;
  background: var(--red);
  box-shadow: 0 0 7px var(--red);
}

.terminal-message {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.terminal-message .prompt {
  color: var(--amber);
}

.terminal-message.typing #terminalText {
  animation: terminal-in 300ms ease-out;
}

.terminal-caret {
  display: inline-block;
  width: 5px;
  height: 9px;
  margin-left: 3px;
  transform: translateY(1px);
  background: var(--red);
  animation: caret-blink 1.1s steps(1) infinite;
}

.terminal-meta {
  color: var(--muted-dim);
  white-space: nowrap;
}

.meta-sep {
  margin: 0 4px;
  color: var(--red);
}

/* ─────────────────────── TOASTS ─────────────────────── */

.toast-layer {
  position: fixed;
  top: 96px;
  right: 24px;
  z-index: 50;
  display: flex;
  width: min(330px, calc(100vw - 32px));
  flex-direction: column;
  gap: 7px;
  pointer-events: none;
}

.toast {
  position: relative;
  display: flex;
  gap: 9px;
  align-items: flex-start;
  padding: 10px 12px;
  border: 1px solid rgba(255, 77, 105, 0.33);
  background:
    linear-gradient(120deg, rgba(35, 12, 21, 0.97), rgba(10, 7, 12, 0.97));
  box-shadow: 0 12px 36px rgba(0, 0, 0, 0.4), 0 0 22px rgba(255, 53, 87, 0.08);
  animation: toast-in 260ms cubic-bezier(0.16, 1, 0.3, 1);
  pointer-events: auto;
  clip-path: polygon(0 0, calc(100% - 8px) 0, 100% 8px, 100% 100%, 8px 100%, 0 calc(100% - 8px));
}

.toast.leaving {
  animation: toast-out 240ms ease-in forwards;
}

.toast-icon {
  display: grid;
  flex: 0 0 auto;
  width: 22px;
  height: 22px;
  place-items: center;
  color: var(--amber);
  border: 1px solid rgba(255, 209, 102, 0.3);
  font-family: var(--font-mono);
  font-size: 10px;
  font-weight: 800;
}

.toast-copy {
  display: flex;
  flex-direction: column;
  gap: 3px;
  min-width: 0;
}

.toast-title {
  color: var(--text);
  font-size: 10px;
  font-weight: 800;
  letter-spacing: 0.1em;
}

.toast-text {
  color: var(--muted);
  font-family: var(--font-mono);
  font-size: 8px;
  line-height: 1.4;
}

.toast.achievement {
  border-color: rgba(255, 209, 102, 0.4);
}

.toast.achievement .toast-icon {
  color: var(--amber);
  background: rgba(255, 209, 102, 0.08);
}

/* ─────────────────────── MODAL ─────────────────────── */

.modal-backdrop {
  position: fixed;
  inset: 0;
  z-index: 100;
  display: grid;
  padding: 20px;
  place-items: center;
  background: rgba(3, 2, 5, 0.76);
  backdrop-filter: blur(7px);
  animation: fade-in 180ms ease-out;
}

.modal-backdrop[hidden] {
  display: none;
}

.modal {
  position: relative;
  width: min(580px, 100%);
  max-height: min(82vh, 730px);
  padding: 24px;
  overflow-y: auto;
  border: 1px solid rgba(255, 77, 105, 0.37);
  background:
    radial-gradient(circle at 90% 4%, rgba(255, 53, 87, 0.1), transparent 36%),
    linear-gradient(145deg, #141018, #09070c);
  box-shadow: 0 30px 100px rgba(0, 0, 0, 0.6), 0 0 60px rgba(255, 53, 87, 0.08);
  clip-path: polygon(0 0, calc(100% - 18px) 0, 100% 18px, 100% 100%, 18px 100%, 0 calc(100% - 18px));
  animation: modal-in 240ms cubic-bezier(0.16, 1, 0.3, 1);
  scrollbar-width: thin;
  scrollbar-color: rgba(255, 53, 87, 0.3) transparent;
}

.modal::before {
  content: "";
  position: absolute;
  top: 0;
  left: 24px;
  width: 72px;
  height: 2px;
  background: var(--red);
  box-shadow: 0 0 12px rgba(255, 53, 87, 0.65);
}

.modal h2 {
  margin: 5px 0 15px;
  font-size: clamp(24px, 4vw, 34px);
  font-weight: 900;
  letter-spacing: 0.13em;
  line-height: 0.95;
}

.modal-close {
  position: absolute;
  top: 14px;
  right: 14px;
  display: grid;
  width: 30px;
  height: 30px;
  padding: 0;
  place-items: center;
  color: var(--muted);
  border: 1px solid rgba(255, 255, 255, 0.1);
  background: transparent;
  font-size: 22px;
  line-height: 1;
  cursor: pointer;
}

.modal-close:hover {
  color: var(--red-hot);
  border-color: var(--line-strong);
}

.help-body {
  display: flex;
  flex-direction: column;
  gap: 8px;
}

.help-step {
  display: flex;
  gap: 11px;
  padding: 9px 10px;
  border: 1px solid rgba(255, 255, 255, 0.055);
  background: rgba(255, 255, 255, 0.016);
}

.help-step > span {
  color: var(--red);
  font-family: var(--font-mono);
  font-size: 10px;
  font-weight: 700;
  line-height: 1.7;
}

.help-step b {
  color: var(--text);
  font-family: var(--font-mono);
  font-size: 9px;
  letter-spacing: 0.1em;
}

.help-step p {
  margin: 3px 0 0;
  color: var(--muted);
  font-size: 11px;
  line-height: 1.4;
}

.help-step kbd {
  height: 16px;
  color: var(--amber);
}

.help-note {
  margin: 4px 0 0;
  color: var(--muted-dim);
  font-family: var(--font-mono);
  font-size: 8px;
  line-height: 1.5;
}

.achievement-summary {
  display: flex;
  align-items: center;
  gap: 12px;
  margin-bottom: 13px;
  padding: 10px;
  border: 1px solid rgba(255, 209, 102, 0.13);
  background: rgba(255, 209, 102, 0.025);
}

.achievement-summary strong {
  color: var(--amber);
  font-family: var(--font-mono);
  font-size: 21px;
}

.achievement-summary span {
  color: var(--muted);
  font-family: var(--font-mono);
  font-size: 8px;
  line-height: 1.5;
}

.achievement-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 8px;
}

.achievement-card {
  display: flex;
  gap: 9px;
  align-items: flex-start;
  padding: 9px;
  border: 1px solid rgba(255, 255, 255, 0.06);
  background: rgba(255, 255, 255, 0.015);
}

.achievement-card.unlocked {
  border-color: rgba(255, 209, 102, 0.25);
  background: rgba(255, 209, 102, 0.035);
}

.achievement-badge {
  display: grid;
  flex: 0 0 auto;
  width: 30px;
  height: 30px;
  place-items: center;
  color: var(--muted-dim);
  border: 1px solid rgba(255, 255, 255, 0.1);
  font-family: var(--font-mono);
  font-size: 10px;
}

.achievement-card.unlocked .achievement-badge {
  color: var(--amber);
  border-color: rgba(255, 209, 102, 0.35);
  background: rgba(255, 209, 102, 0.07);
  box-shadow: 0 0 12px rgba(255, 209, 102, 0.08);
}

.achievement-copy {
  display: flex;
  flex-direction: column;
  gap: 2px;
  min-width: 0;
}

.achievement-copy b {
  color: var(--muted);
  font-size: 9px;
  letter-spacing: 0.06em;
}

.achievement-card.unlocked .achievement-copy b {
  color: var(--text);
}

.achievement-copy span {
  color: var(--muted-dim);
  font-size: 8.5px;
  line-height: 1.3;
}

.modal-actions {
  display: flex;
  justify-content: flex-end;
  gap: 8px;
  margin-top: 18px;
}

.btn-primary,
.btn-ghost {
  min-height: 36px;
  padding: 0 16px;
  font-family: var(--font-mono);
  font-size: 8px;
  font-weight: 700;
  letter-spacing: 0.12em;
  cursor: pointer;
}

.btn-primary {
  color: #0c0607;
  border: 1px solid var(--amber);
  background: var(--amber);
}

.btn-primary:hover {
  filter: brightness(1.12);
}

.btn-ghost {
  color: var(--muted);
  border: 1px solid rgba(255, 255, 255, 0.13);
  background: transparent;
}

.btn-ghost:hover {
  color: var(--text);
  border-color: rgba(255, 255, 255, 0.28);
}

.prestige-modal-body {
  color: var(--muted);
  font-size: 12px;
  line-height: 1.5;
}

.prestige-modal-body p {
  margin: 0 0 10px;
}

.prestige-result {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 10px;
  padding: 12px;
  border: 1px solid rgba(185, 146, 255, 0.22);
  background: rgba(185, 146, 255, 0.055);
}

.prestige-result span {
  color: var(--muted);
  font-family: var(--font-mono);
  font-size: 8px;
  letter-spacing: 0.08em;
}

.prestige-result strong {
  color: var(--violet);
  font-family: var(--font-mono);
  font-size: 17px;
}

/* ─────────────────────── ANIMATIONS ─────────────────────── */

@keyframes status-blink {
  0%, 100% { opacity: 1; }
  50% { opacity: 0.28; }
}

@keyframes host-pulse {
  0% { transform: scale(0.85); opacity: 0.8; }
  100% { transform: scale(1.25); opacity: 0; }
}

@keyframes orbit-spin {
  to { transform: rotate(360deg); }
}

@keyframes orbit-spin-reverse {
  to { transform: rotate(-360deg); }
}

@keyframes halo-breathe {
  0%, 100% { opacity: 0.7; transform: scale(0.94); }
  50% { opacity: 1; transform: scale(1.06); }
}

@keyframes sigil-float {
  0%, 100% { transform: translateY(0) scale(1); }
  50% { transform: translateY(-3px) scale(1.015); }
}

@keyframes sigil-dash {
  to { stroke-dashoffset: -80; }
}

@keyframes core-hit {
  0% { transform: scale(1); }
  35% { transform: scale(0.952); }
  100% { transform: scale(1); }
}

@keyframes core-pulse {
  0% { transform: scale(1); opacity: 0.7; }
  100% { transform: scale(1.19); opacity: 0; }
}

@keyframes ability-ready {
  0%, 100% { box-shadow: inset 0 0 0 rgba(255, 53, 87, 0); }
  50% { box-shadow: inset 0 0 24px rgba(255, 53, 87, 0.2), 0 0 12px rgba(255, 53, 87, 0.14); }
}

@keyframes float-up {
  0% { opacity: 1; transform: translate(-50%, 0) scale(0.9); }
  22% { opacity: 1; transform: translate(-50%, -14px) scale(1.08); }
  100% { opacity: 0; transform: translate(-50%, -56px) scale(0.92); }
}

@keyframes spark-fly {
  0% { opacity: 1; transform: translate(-50%, -50%) rotate(0) scale(1); }
  100% { opacity: 0; transform: translate(calc(-50% + var(--dx)), calc(-50% + var(--dy))) rotate(80deg) scale(0.2); }
}

@keyframes anomaly-in {
  from { opacity: 0; transform: translate(-50%, -50%) scale(2.4) rotate(-20deg); }
  to { opacity: 1; transform: translate(-50%, -50%) scale(1) rotate(0); }
}

@keyframes anomaly-pulse {
  0%, 100% { box-shadow: 0 0 22px rgba(255, 53, 87, 0.42), inset 0 0 10px rgba(255, 53, 87, 0.2); }
  50% { box-shadow: 0 0 38px rgba(255, 53, 87, 0.72), inset 0 0 17px rgba(255, 53, 87, 0.33); }
}

@keyframes terminal-in {
  from { opacity: 0; transform: translateY(3px); }
  to { opacity: 1; transform: translateY(0); }
}

@keyframes caret-blink {
  0%, 49% { opacity: 1; }
  50%, 100% { opacity: 0; }
}

@keyframes toast-in {
  from { opacity: 0; transform: translateX(24px); }
  to { opacity: 1; transform: translateX(0); }
}

@keyframes toast-out {
  to { opacity: 0; transform: translateX(24px); }
}

@keyframes modal-in {
  from { opacity: 0; transform: translateY(12px) scale(0.985); }
  to { opacity: 1; transform: translateY(0) scale(1); }
}

@keyframes fade-in {
  from { opacity: 0; }
  to { opacity: 1; }
}

@keyframes glitch-flash {
  0% { opacity: 0; transform: translateX(0); }
  20% { opacity: 0.9; transform: translateX(-9px); }
  40% { opacity: 0.25; transform: translateX(5px); }
  60% { opacity: 0.65; transform: translateX(-3px); }
  100% { opacity: 0; transform: translateX(0); }
}

@keyframes shell-shake {
  0%, 100% { transform: translate(0, 0); }
  20% { transform: translate(-3px, 1px); }
  40% { transform: translate(3px, -1px); }
  60% { transform: translate(-2px, -1px); }
  80% { transform: translate(2px, 1px); }
}

/* ─────────────────────── RESPONSIVE ─────────────────────── */

@media (max-width: 1240px) {
  .game-grid {
    grid-template-columns: 256px minmax(330px, 1fr) 340px;
    padding-right: 16px;
    padding-left: 16px;
  }

  .topbar {
    padding-right: 18px;
    padding-left: 18px;
  }

  .top-stats {
    gap: 10px;
    padding-right: 12px;
    padding-left: 12px;
  }

  .top-stat {
    min-width: 80px;
  }

  .top-stat:first-child {
    min-width: 100px;
  }

  .readout strong {
    font-size: 12px;
  }

  .shop-item {
    grid-template-columns: 32px minmax(0, 1fr) auto;
    gap: 6px;
    padding-right: 6px;
    padding-left: 6px;
  }

  .shop-icon {
    width: 32px;
    height: 34px;
  }

  .shop-icon svg {
    width: 21px;
    height: 21px;
  }

  .shop-buy {
    min-width: 59px;
  }
}

@media (max-width: 1040px) {
  body {
    overflow-y: auto;
  }

  .game-shell {
    height: auto;
    min-height: 100dvh;
    grid-template-rows: auto auto auto;
  }

  .topbar {
    grid-template-columns: 1fr auto;
    gap: 10px 16px;
  }

  .top-stats {
    grid-column: 1 / -1;
    justify-content: center;
    order: 3;
    padding: 7px 14px;
  }

  .top-stat,
  .top-stat:first-child {
    min-width: 0;
    flex: 1;
  }

  .top-stat {
    align-items: center;
  }

  .top-actions {
    grid-column: 2;
    grid-row: 1;
  }

  .game-grid {
    grid-template-columns: minmax(0, 1fr) 330px;
    grid-template-areas:
      "core shop"
      "system shop";
    padding-bottom: 20px;
  }

  .core-stage {
    grid-area: core;
    min-height: 580px;
    overflow: visible;
  }

  .system-panel {
    grid-area: system;
    overflow: visible;
  }

  .system-panel > *:not(.panel-heading) {
    margin-right: 18px;
    margin-left: 18px;
  }

  .shop-panel {
    grid-area: shop;
    max-height: 760px;
  }

  .reactor {
    width: min(52vw, 450px);
  }

  .terminal-bar {
    position: sticky;
    bottom: 0;
    z-index: 20;
    height: 34px;
    backdrop-filter: blur(8px);
  }
}

@media (max-width: 760px) {
  .topbar {
    padding: 10px 14px;
    min-height: 72px;
  }

  .brand-mark {
    width: 40px;
    height: 40px;
  }

  .brand-mark svg {
    width: 31px;
    height: 31px;
  }

  .brand-title {
    font-size: 21px;
  }

  .eyebrow {
    font-size: 7px;
  }

  .top-stat .stat-label {
    font-size: 7px;
  }

  .stat-value {
    font-size: 15px;
  }

  .top-actions {
    gap: 4px;
  }

  .icon-btn {
    width: 32px;
    height: 32px;
  }

  .game-grid {
    grid-template-columns: minmax(0, 1fr);
    grid-template-areas:
      "core"
      "system"
      "shop";
    padding: 10px 10px 20px;
    gap: 10px;
  }

  .core-stage {
    min-height: 500px;
  }

  .reactor {
    width: min(88vw, 410px);
  }

  .stage-status {
    font-size: 7px;
  }

  .combo-readout {
    font-size: 7px;
  }

  .runes {
    display: none;
  }

  .core-hint {
    font-size: 7px;
  }

  .stage-bottom {
    gap: 12px;
  }

  .tick-stat {
    min-width: 0;
  }

  .system-panel,
  .shop-panel {
    max-height: none;
  }

  .shop-list {
    overflow: visible;
  }

  .achievements-link {
    margin-top: 10px;
  }

  .terminal-bar {
    grid-template-columns: auto minmax(0, 1fr);
    gap: 8px;
    padding: 0 12px;
  }

  .terminal-meta {
    display: none;
  }

  .modal {
    padding: 20px;
  }

  .achievement-grid {
    grid-template-columns: 1fr;
  }

  .toast-layer {
    top: 88px;
    right: 12px;
  }
}

@media (max-width: 430px) {
  .brand-title {
    font-size: 18px;
    letter-spacing: 0.04em;
  }

  .brand {
    gap: 9px;
  }

  .brand-mark {
    width: 35px;
    height: 35px;
  }

  .icon-btn {
    width: 29px;
    height: 29px;
  }

  .top-stats {
    gap: 5px;
    padding: 6px 9px;
  }

  .stat-value {
    font-size: 13px;
  }

  .cores-stat {
    display: none;
  }

  .top-stats .stat-divider:last-of-type {
    display: none;
  }

  .core-stage {
    min-height: 465px;
  }

  .reactor {
    width: min(91vw, 370px);
  }

  .solver-core {
    width: 64%;
  }

  .stage-status {
    letter-spacing: 0.03em;
  }

  .stage-status i {
    display: none;
  }

  .core-hint {
    max-width: 280px;
  }
}

@media (max-height: 720px) and (min-width: 1041px) {
  .topbar {
    min-height: 68px;
    padding-top: 8px;
    padding-bottom: 8px;
  }

  .topbar::after {
    top: 67px;
  }

  .brand-title {
    font-size: 25px;
  }

  .brand-mark {
    width: 41px;
    height: 41px;
  }

  .reactor {
    width: min(52vh, 400px);
  }

  .panel-heading {
    padding-top: 11px;
    padding-bottom: 9px;
  }

  .host-card {
    margin-top: 8px;
    padding: 6px;
  }

  .host-face {
    width: 39px;
    height: 39px;
  }

  .host-face svg {
    width: 30px;
    height: 30px;
  }

  .readout {
    padding-top: 6px;
    padding-bottom: 6px;
  }

  .ability-card,
  .prestige-card {
    margin-top: 7px;
    padding: 8px;
  }

  .achievements-link {
    min-height: 32px;
  }

  .shop-item {
    min-height: 50px;
    padding-top: 5px;
    padding-bottom: 5px;
  }

  .shop-tabs {
    margin-top: 8px;
  }

  .buy-mode-row {
    padding-top: 6px;
    padding-bottom: 5px;
  }

  .shop-tip {
    margin-top: 5px;
    padding-top: 6px;
  }
}

@media (prefers-reduced-motion: reduce) {
  *,
  *::before,
  *::after {
    animation-duration: 0.01ms !important;
    animation-iteration-count: 1 !important;
    scroll-behavior: auto !important;
    transition-duration: 0.01ms !important;
  }
}

